import idle.core.*;import idle.core.upgrades.*;import idle.core.darkmatter.*;import idle.core.bigbang.*;import java.util.*;
public class RobotPhase5 {
 static void particle(Game g){for(int i=0;i<1200;i++){Upgrade b=null;for(Upgrade u:g.upgrades(Resource.PARTICLES))if(g.canBuy(u.id())&&(b==null||g.costOf(u.id()).lt(g.costOf(b.id()))))b=u;if(b==null)break;g.buy(b.id());}}
 static void atom(Game g){for(int i=0;i<150;i++){Upgrade b=null;for(Upgrade u:g.upgrades(Resource.ATOMS))if(!u.id().equals("atom_keep")&&g.canBuy(u.id())&&(b==null||g.costOf(u.id()).lt(g.costOf(b.id()))))b=u;if(b==null)break;g.buy(b.id());}}
 static void dark(Game g){for(int i=0;i<100;i++){boolean bought=false;for(DarkUpgrade u:g.darkUpgrades())if(g.canBuyDark(u.id())){g.buyDark(u.id());bought=true;break;}if(!bought)break;}}
 public static void main(String[]args){String mode=args.length>0?args[0]:"fast";Game g=new Game(new GameState(),Upgrades.DEFAULT,Automations.DEFAULT,DarkUpgrades.DEFAULT,idle.core.achievements.Achievements.DEFAULT,new Random(1));g.start();double t=0,started=-1;int lastHour=-1;while(t<12*3600){boolean special=g.inChallenge()&&g.activeChallenge().id().equals("challenge_volatile");double dt=special?(mode.equals("fast")?0.05:0.25):1.;g.tick(dt);t+=dt;particle(g);for(int i=0;i<5&&g.canFuse();i++){g.fuse();atom(g);particle(g);}for(Automation a:g.automations())if(g.canBuyAutomation(a.id()))g.buyAutomation(a.id());for(Automation a:g.automations())if(g.canSpeedUpAutomation(a.id()))g.speedUpAutomation(a.id());atom(g);for(int i=0;i<15&&g.canSynthesize();i++)g.synthesize();dark(g);if(!g.inChallenge()){for(Challenge c:g.challenges())if(g.isChallengeUnlocked(c.id())&&!g.isChallengeCompleted(c.id())){if(g.startChallenge(c.id())){System.out.printf("START,%.1f,%s%n",t,c.id());if(c.id().equals("challenge_volatile"))started=t;}break;}}if(g.canExplode()){String c=g.inChallenge()?g.activeChallenge().id():"ordinary";g.explode();System.out.printf("EXP,%.1f,%d,%s,%d%n",t,g.state().explosions(),c,g.completedChallenges());if(c.equals("challenge_volatile"))break;}int h=(int)(t/3600);if(h!=lastHour){lastHour=h;System.out.printf("HOUR,%d,%d,%d,%s%n",h,g.discoveredElements(),g.state().explosions(),g.state().particles());}if(special&&t-started>3600){System.out.printf("VOLATILE_1H,%.1f,%d,%s,%s%n",t,g.discoveredElements(),g.state().particles(),g.state().atoms());System.out.printf("DETAIL,speed=%d,gen=%d,coupling=%d,pps=%s,genCost=%s,speedCost=%s%n",g.levelOf("speed"),g.levelOf("generator"),g.levelOf("coupling"),g.productionPerSecond(),g.costOf("generator"),g.costOf("speed"));break;}}System.out.printf("END,%.1f,%d,%d,%s%n",t,g.discoveredElements(),g.completedChallenges(),g.inChallenge()?g.activeChallenge().id():"none");}
}
